using WindowsSearch.Common.Serialization;
using WindowsSearch.Common.Logging;
using System.Windows; using System.Collections.ObjectModel; using WindowsSearch.Common.Models; using Hub.Models.Settings; using Hub.Services.Settings;  namespace Hub;  public partial class SettingsWindow : Window {     private readonly AppSettingsService settingsService;     private readonly ProviderSettingsService providerSettingsService;     private readonly Action<AppSettings> onSaved;     private readonly ObservableCollection<ProviderSettingsModel> providers = new();     private readonly ObservableCollection<ProviderSettingsEntry> providerEntries = new();      public SettingsWindow(AppSettingsService settingsService, AppSettings currentSettings, Action<AppSettings> onSaved)     {         InitializeComponent();         this.settingsService = settingsService;         providerSettingsService = new ProviderSettingsService();         this.onSaved = onSaved;          ImageResolverComboBox.ItemsSource = Enum.GetNames<ImageResolverKind>();         TransportComboBox.ItemsSource = Enum.GetNames<ProviderTransportKind>();         SerializationComboBox.ItemsSource = Enum.GetNames<SerializationKind>();         LogLevelComboBox.ItemsSource = Enum.GetNames<LogLevel>();         ProviderLogLevelComboBox.ItemsSource = Enum.GetNames<LogLevel>();          ProviderSettingsGrid.ItemsSource = providerEntries;          foreach (var provider in providerSettingsService.LoadAll())         {             providers.Add(provider);         }          ProviderComboBox.ItemsSource = providers;         ProviderComboBox.DisplayMemberPath = nameof(ProviderSettingsModel.ProviderName);          ImageResolverComboBox.SelectedItem = currentSettings.ImageResolverKind.ToString();         TransportComboBox.SelectedItem = currentSettings.ProviderTransportKind.ToString();         SerializationComboBox.SelectedItem = currentSettings.ProviderSerialization.ToString();         LogLevelComboBox.SelectedItem = currentSettings.LogLevel.ToString();         TimeoutTextBox.Text = currentSettings.ProviderTimeoutSeconds.ToString();         SearchLimitTextBox.Text = currentSettings.SearchLimit.ToString();          if (providers.Count > 0)         {             ProviderComboBox.SelectedIndex = 0;         }     }      private void ProviderComboBox_SelectionChanged(object sender, System.Windows.Controls.SelectionChangedEventArgs e)     {         if (ProviderComboBox.SelectedItem is not ProviderSettingsModel selected)         {             return;         }          ProviderEndpointNamedPipeTextBox.Text = selected.Document.EndpointNamedPipe;         ProviderEndpointHttpTextBox.Text = selected.Document.EndpointHttp;         ProviderEndpointGrpcTextBox.Text = selected.Document.EndpointGrpc;         ProviderTimeoutTextBox.Text = selected.Document.TimeoutSeconds.ToString();         ProviderLogLevelComboBox.SelectedItem = selected.Document.LogLevel;          providerEntries.Clear();         foreach (var pair in selected.Document.Settings)         {             providerEntries.Add(new ProviderSettingsEntry { Key = pair.Key, Value = pair.Value });         }     }      private void SaveButton_Click(object sender, RoutedEventArgs e)     {         if (!Enum.TryParse<ImageResolverKind>(ImageResolverComboBox.SelectedItem as string, true, out var resolverKind))         {             System.Windows.MessageBox.Show("Select a valid image resolver.", "Invalid settings", MessageBoxButton.OK, MessageBoxImage.Warning);             return;         }          if (!Enum.TryParse<ProviderTransportKind>(TransportComboBox.SelectedItem as string, true, out var transportKind))         {             System.Windows.MessageBox.Show("Select a valid provider transport.", "Invalid settings", MessageBoxButton.OK, MessageBoxImage.Warning);             return;         }          if (!Enum.TryParse<SerializationKind>(SerializationComboBox.SelectedItem as string, true, out var serializationKind))         {             System.Windows.MessageBox.Show("Select a valid serialization type.", "Invalid settings", MessageBoxButton.OK, MessageBoxImage.Warning);             return;         }          if (!Enum.TryParse<LogLevel>(LogLevelComboBox.SelectedItem as string, true, out var hubLogLevel))         {             System.Windows.MessageBox.Show("Select a valid log level.", "Invalid settings", MessageBoxButton.OK, MessageBoxImage.Warning);             return;         }          if (!int.TryParse(TimeoutTextBox.Text, out var timeoutSeconds) || timeoutSeconds <= 0)         {             System.Windows.MessageBox.Show("Provider timeout must be a positive number.", "Invalid settings", MessageBoxButton.OK, MessageBoxImage.Warning);             return;         }          if (!int.TryParse(SearchLimitTextBox.Text, out var searchLimit) || searchLimit <= 0)         {             System.Windows.MessageBox.Show("Search limit must be a positive number.", "Invalid settings", MessageBoxButton.OK, MessageBoxImage.Warning);             return;         }          var updatedSettings = new AppSettings         {             ImageResolverKind = resolverKind,             ProviderTransportKind = transportKind,             ProviderSerialization = serializationKind,             ProviderTimeoutSeconds = timeoutSeconds,             LogLevel = hubLogLevel,             SearchLimit = searchLimit,         };          var validationErrors = settingsService.Save(updatedSettings);         if (validationErrors.Count > 0)         {             System.Windows.MessageBox.Show(string.Join(Environment.NewLine, validationErrors), "Invalid settings", MessageBoxButton.OK, MessageBoxImage.Warning);             return;         }          if (ProviderComboBox.SelectedItem is ProviderSettingsModel selectedProvider)         {             if (!int.TryParse(ProviderTimeoutTextBox.Text, out var providerTimeoutSeconds) || providerTimeoutSeconds <= 0)             {                 System.Windows.MessageBox.Show("Provider timeout must be a positive number.", "Invalid settings", MessageBoxButton.OK, MessageBoxImage.Warning);                 return;             }              if (!Enum.TryParse<LogLevel>(ProviderLogLevelComboBox.SelectedItem as string, true, out var providerLogLevel))             {                 System.Windows.MessageBox.Show("Select a valid provider log level.", "Invalid settings", MessageBoxButton.OK, MessageBoxImage.Warning);                 return;             }              selectedProvider.Document.EndpointNamedPipe = ProviderEndpointNamedPipeTextBox.Text.Trim();             selectedProvider.Document.EndpointHttp = ProviderEndpointHttpTextBox.Text.Trim();             selectedProvider.Document.EndpointGrpc = ProviderEndpointGrpcTextBox.Text.Trim();             selectedProvider.Document.LogLevel = providerLogLevel.ToString();              var validationContext = new System.ComponentModel.DataAnnotations.ValidationContext(selectedProvider.Document);             var validationResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();             if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(selectedProvider.Document, validationContext, validationResults, true))             {                 var errors = string.Join(Environment.NewLine, validationResults.Select(r => r.ErrorMessage));                 System.Windows.MessageBox.Show(errors, "Invalid provider settings", MessageBoxButton.OK, MessageBoxImage.Warning);                 return;             }              selectedProvider.Document.TimeoutSeconds = providerTimeoutSeconds;             selectedProvider.Document.Settings = providerEntries                 .Where(entry => !string.IsNullOrWhiteSpace(entry.Key))                 .ToDictionary(entry => entry.Key.Trim(), entry => entry.Value ?? string.Empty, StringComparer.OrdinalIgnoreCase);              var providerSaveErrors = providerSettingsService.Save(selectedProvider);             if (providerSaveErrors.Count > 0)             {                 System.Windows.MessageBox.Show(string.Join(Environment.NewLine, providerSaveErrors), "Invalid provider settings", MessageBoxButton.OK, MessageBoxImage.Warning);                 return;             }         }          onSaved(updatedSettings);         Close();     }      private void CancelButton_Click(object sender, RoutedEventArgs e)     {         Close();     } }
